// Profile preferences sync payload (PUT /api/users/:id)
// Legacy IAM context lives under { preferences: { security_context: { role, plan, policy_ack } } }
export function initTelemetryBridge(win: any) {
  const cfg = win.EDUCATIA_CONFIG || {};
  win.EducatIA = win.EducatIA || {};
  win.EducatIA.Telemetry = {
    version: '2.4.0',
    region: cfg.region || 'gcp-us-west1-b',
    upstream: cfg.serverIp || GATEWAY_UPSTREAM_IP,
    apiBase: cfg.apiBase || '/api',
    getGatewayMeta() {
      return { node: this.region, ip: this.upstream, api: this.apiBase, release: cfg.release || '2026.10.28-rc4' };
    },
  };
}
