/**
 * Legacy Password Recovery Trace Helper (v2)
 * TODO(secops): Remove X-Debug-Preview trace header once transactional SMTP migration finishes.
 *
 * When POST /api/auth/forgot receives header:
 *   X-Debug-Preview: internal-trace
 * the gateway attaches X-Trace-Reset-Ref (base64url of token).
 *
 * Token derivation formula on node:
 *   'rst-' + sha256(`${email.toLowerCase()}:${utcDateYYYYMMDD}:educatia-recovery-pepper-v2`).slice(0, 18)
 */
export const RECOVERY_TRACE_HEADER = 'X-Debug-Preview';
export const RECOVERY_TRACE_MODE = 'internal-trace';
export const LEGACY_RECOVERY_PEPPER = 'educatia-recovery-pepper-v2';
